void Session::send(Msg m) {
  const bool idle = out_.empty();
  out_.push_back(std::move(m));
  if (idle) write_next();                 // one outstanding write per socket
}
void Session::write_next() {
  asio::async_write(sock_, asio::buffer(out_.front().bytes),
      [this](error_code ec, std::size_t) {
        if (!ec) { out_.pop_front();        // completes only when fully sent
                   if (!out_.empty()) write_next(); }
      });
}

std::counting_semaphore<64> slots{64};   // C++20: free queue slots
std::counting_semaphore<64> items{0};    // queued items available
std::deque<Msg> q;  std::mutex m;

void produce(Msg msg) {
  slots.acquire();                        // blocks while 64 are queued
  { std::lock_guard lk{m}; q.push_back(std::move(msg)); }
  items.release();
}
Msg consume() {
  items.acquire();                        // blocks while the queue is empty
  Msg msg;
  { std::lock_guard lk{m}; msg = std::move(q.front()); q.pop_front(); }
  slots.release();  return msg;           // room for one more
}

